INSERT INTO ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID) SELECT r.ID, p.ID FROM ROLES r, PERMISSIONS p WHERE r.CODE = 'ADMIN';
INSERT INTO ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID) SELECT r.ID, p.ID FROM ROLES r, PERMISSIONS p WHERE r.CODE = 'MANAGER' AND p.CODE IN ( 'BOOK_VIEW', 'BOOK_EXPORT', 'COPY_VIEW', 'COPY_WITHDRAW', 'MEMBER_VIEW', 'MEMBER_LOCK', 'MEMBER_TYPE_MANAGE', 'LOAN_VIEW', 'RESERVATION_VIEW', 'FINE_VIEW', 'FINE_WAIVE', 'REPORT_VIEW', 'REPORT_OVERDUE', 'REPORT_REVENUE', 'REPORT_INVENTORY', 'REPORT_EXPORT', 'USER_VIEW', 'USER_MANAGE', 'SETTING_MANAGE', 'HOLIDAY_MANAGE', 'AUDIT_LOG_VIEW' );
INSERT INTO ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID) SELECT r.ID, p.ID FROM ROLES r, PERMISSIONS p WHERE r.CODE = 'LIBRARIAN' AND p.CODE IN ( 'BOOK_VIEW', 'COPY_VIEW', 'MEMBER_VIEW', 'MEMBER_CREATE', 'MEMBER_EDIT', 'MEMBER_LOCK', 'MEMBER_CARD_RENEW', 'LOAN_VIEW', 'LOAN_CREATE', 'LOAN_RETURN', 'LOAN_RENEW', 'RESERVATION_VIEW', 'RESERVATION_MANAGE', 'RESERVATION_CANCEL', 'FINE_VIEW', 'FINE_CREATE', 'FINE_PAYMENT', 'FINE_WAIVE', 'REPORT_VIEW', 'REPORT_OVERDUE', 'NOTIFICATION_MANAGE' );
INSERT INTO ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID) SELECT r.ID, p.ID FROM ROLES r, PERMISSIONS p WHERE r.CODE = 'CATALOGER' AND p.CODE IN ( 'BOOK_VIEW', 'BOOK_CREATE', 'BOOK_EDIT', 'BOOK_DELETE', 'BOOK_IMPORT', 'BOOK_EXPORT', 'AUTHOR_MANAGE', 'CATEGORY_MANAGE', 'PUBLISHER_MANAGE', 'LOCATION_MANAGE', 'COPY_VIEW', 'COPY_CREATE', 'COPY_EDIT', 'COPY_WITHDRAW', 'REPORT_INVENTORY' );
INSERT INTO ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID) SELECT r.ID, p.ID FROM ROLES r, PERMISSIONS p WHERE r.CODE = 'READER' AND p.CODE IN ( 'BOOK_VIEW', 'LOAN_VIEW', 'LOAN_RENEW', 'RESERVATION_VIEW', 'RESERVATION_MANAGE', 'RESERVATION_CANCEL', 'FINE_VIEW' );
UPDATE USER_ SET ROLE_ID = (SELECT ID FROM ROLES WHERE CODE = 'ADMIN') WHERE USERNAME = 'admin';
